-- 0003_rls_policies.sql
-- Every Base44 RLS rule translated 1:1:
--   {{user.id}}             -> auth.uid()
--   {{user.email}}          -> (auth.jwt() ->> 'email')
--   {{user.data.vendor_id}} -> public.current_vendor_id()
--   {{user.data.<key>}}     -> public.current_user_data('<key>')
--   user_condition.role     -> public.is_admin() / public.current_role_name()
-- Read policies that contain a public data condition (approval_status = 'approved', status = 'active', …)
-- stay readable without login so the storefront works; everything else needs a signed-in user.
-- Rules the Base44 entity left out are kept open, exactly like Base44's default (listed in the README).

alter table public."advertisement" enable row level security;
drop policy if exists "advertisement_select" on public."advertisement";
create policy "advertisement_select" on public."advertisement" for select to anon, authenticated using ((("status" = 'active') or ("created_by_id" = auth.uid()) or ("vendor_id" = public.current_vendor_id()) or public.is_admin()));
drop policy if exists "advertisement_insert" on public."advertisement";
create policy "advertisement_insert" on public."advertisement" for insert to authenticated with check (("created_by_id" = auth.uid()));
drop policy if exists "advertisement_update" on public."advertisement";
create policy "advertisement_update" on public."advertisement" for update to authenticated using ((("created_by_id" = auth.uid()) or ("vendor_id" = public.current_vendor_id()) or public.is_admin())) with check ((("created_by_id" = auth.uid()) or ("vendor_id" = public.current_vendor_id()) or public.is_admin()));
drop policy if exists "advertisement_delete" on public."advertisement";
create policy "advertisement_delete" on public."advertisement" for delete to authenticated using ((("created_by_id" = auth.uid()) or public.is_admin()));
